const $=s=>document.querySelector(s);let tasks=[],current=null,selectedRound=null,configured=false,polling=false;
const labels={queued:'等待处理',running:'处理中',passed:'审核通过',blocked:'需人工处理',failed:'运行失败',interrupted:'连接中断'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>new Date(t*1000).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const pill=s=>`<span class="pill ${esc(s)}">${labels[s]||esc(s)}</span>`;
const empty=(title,body)=>`<div class="empty"><div class="empty-symbol">◇</div><h2>${title}</h2><p>${body}</p></div>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',6000)}
async function api(path,options){const r=await fetch(path,options),d=await r.json();if(!r.ok){const error=Error(d.error||'请求失败');error.status=r.status;throw error}return d}
function navigate(){selectedRound=null;render()}
function route(){return location.hash.slice(1)||'new'}
function render(){const r=route();document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===(r.startsWith('task/')?'history':r)));$('#crumb').textContent=r==='upload'?'上传海报审核':r==='history'?'任务记录':r==='guide'?'工作流说明':r.startsWith('task/')?'任务详情':'创建海报';if(r==='upload')uploadPage();else if(r==='history')historyPage();else if(r==='guide')guidePage();else if(r.startsWith('task/'))detailPage(r.split('/')[1]);else newPage()}
function newPage(){current=null;$('#main').innerHTML=`<div class="eyebrow">CREATE & REVIEW</div><h1>从一份需求，开始创作</h1><p class="lead">生成海报后自动审核；发现风险时修改并复审，通过后即可导出。</p><div class="mode-entry"><span>已经有海报了？</span><a href="#upload">上传图片直接审核 →</a></div><div class="layout"><section class="card"><div class="section-head"><h2>海报需求</h2><button class="text-btn" id="example">填入示例</button></div><div id="form-error"></div><form id="create-form"><div class="field"><label for="product_name">产品名称<span class="required">*</span></label><input id="product_name" name="product_name" required maxlength="5000" placeholder="例如：简素帆布袋" autocomplete="off"></div><div class="field"><label for="product_facts">产品真实信息<span class="required">*</span></label><textarea id="product_facts" name="product_facts" required maxlength="5000" placeholder="说明材质、规格、用途等已确认的事实；涉及认证、功效或数据时，请提供依据。"></textarea><p class="hint">审核以这些事实为基础，请不要填写未经证实的宣传结论。</p></div><div class="field"><label for="design_request">设计与文案要求<span class="required">*</span></label><textarea id="design_request" name="design_request" required maxlength="5000" placeholder="描述画面风格、配色、场景，以及希望出现在海报上的文字。"></textarea><p class="hint">默认生成竖版海报，发现风险后最多自动修改两次。</p></div><div class="form-bottom"><span class="quiet">提交后可在任务记录中查看进度</span><button class="btn primary" type="submit" id="submit">生成并审核 <span>→</span></button></div></form></section><div class="right-col"><section class="card"><h2>每张海报，都经过审核</h2><ol class="flow"><li><strong>生成海报</strong><small>根据产品事实与设计要求创作</small></li><li><strong>识别实际画面</strong><small>读取成图中的文字与视觉内容</small></li><li><strong>依据法规审核</strong><small>定位风险，给出依据与修改建议</small></li><li><strong>通过后导出</strong><small>有风险自动修改，修改后再次审核</small></li></ol><div class="note"><strong>遇到无法确认的内容怎么办？</strong>识别不清或需要补充依据时，任务会停止导出并保留审核记录，供人工核实。</div></section><section class="card spaced"><h3>本次审核依据</h3><p class="quiet">《中华人民共和国广告法》<br>来自已提供的法规文件</p><a class="text-btn" href="#guide">了解工作流如何执行 →</a></section></div></div>`;
$('#example').onclick=()=>{const values={product_name:'简素帆布袋',product_facts:'普通棉质帆布袋，米白色，尺寸35×40厘米。无认证、排名、销量或功效声明。用于日常随身收纳。',design_request:'竖版简洁海报，米白色背景，一个无标志的棉质帆布袋。画面仅出现两行清晰中文：简素帆布袋；日常随行。不要添加其他文字、价格、认证、徽章或人物。'};for(const [k,v] of Object.entries(values))$('#'+k).value=v};
$('#create-form').onsubmit=submitForm;
if(!window.pendingInputs&&pendingSubmission)window.pendingInputs=pendingSubmission.inputs;
if(window.pendingInputs){for(const [k,v]of Object.entries(window.pendingInputs))$('#'+k).value=v;window.pendingInputs=null}
}
let pendingSubmission=null;try{pendingSubmission=JSON.parse(sessionStorage.getItem('pendingSubmission')||'null')}catch{}
let requestKey=pendingSubmission?.request_key||null;
async function submitForm(e){e.preventDefault();const button=$('#submit');button.disabled=true;button.textContent='正在提交…';$('#form-error').textContent='';const inputs=Object.fromEntries(new FormData(e.target));if(pendingSubmission&&JSON.stringify(pendingSubmission.inputs)!==JSON.stringify(inputs)){button.disabled=false;button.textContent='生成并审核 →';$('#form-error').innerHTML='<p class="error-banner">上一次提交的结果尚未确认，请先查看任务记录；确认后使用“补充需求重新提交”。</p>';return}requestKey=requestKey||crypto.randomUUID();pendingSubmission={inputs,request_key:requestKey};sessionStorage.setItem('pendingSubmission',JSON.stringify(pendingSubmission));try{const t=await api('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({inputs,request_key:requestKey})});requestKey=null;pendingSubmission=null;sessionStorage.removeItem('pendingSubmission');tasks=[t,...tasks.filter(x=>x.id!==t.id)];location.hash='task/'+t.id}catch(err){if(err.status&&err.status!==409){requestKey=null;pendingSubmission=null;sessionStorage.removeItem('pendingSubmission')}$('#form-error').innerHTML=`<p class="error-banner">${esc(err.message)}</p>`;button.disabled=false;button.textContent='生成并审核 →'}}
function historyPage(){current=null;const count=s=>tasks.filter(x=>x.status===s).length;$('#main').innerHTML=`<div class="topline"><div><div class="eyebrow">REVIEW ARCHIVE</div><h1>每一次创作，都有记录</h1></div><a class="btn primary" href="#new">＋ 创建海报</a></div><p class="lead">查看海报版本、风险依据和最终结果。</p><div class="stats"><span>全部任务 <b>${tasks.length}</b></span><span>审核通过 <b>${count('passed')}</b></span><span>处理中 <b>${count('running')+count('queued')}</b></span><span>需人工处理 <b>${count('blocked')}</b></span></div><section class="card">${tasks.length?`<div class="table-wrap"><table><thead><tr><th>海报任务</th><th>提交时间</th><th>状态</th><th>版本</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><a class="task-title" href="#task/${t.id}">${esc(t.inputs.product_name)}</a><div class="task-meta">${(t.mode==='upload'?'上传审核':'生成审核')} · ${t.id.slice(0,8).toUpperCase()}</div></td><td>${date(t.created_at)}</td><td>${pill(t.status)}</td><td>${t.rounds.length||'—'}</td><td><a class="text-btn" href="#task/${t.id}">查看详情 →</a></td></tr>`).join('')}</tbody></table></div>`:empty('还没有海报任务','创建第一份需求，生成与审核记录会保存在这里。')}</section>`}
function riskMarkup(report){if(!report)return '<p class="quiet">该版本尚未完成审核。</p>';let summary=report.summary||report.reason||'';if(typeof summary!=='string')summary=JSON.stringify(summary);return `<span class="pill ${report.decision==='PASS'?'passed':'blocked'}">${{PASS:'未发现风险',REVISE:'发现风险',HUMAN:'需要人工核实'}[report.decision]||'待核实'}</span><p class="report-summary">${esc(summary)}</p>${(report.risks||[]).map((r,i)=>`<div class="risk"><strong>${i+1}. ${esc(r.category||r.type||r.risk_type||r.issue||'风险内容')}</strong><p>${esc(r.evidence||r.description||'')}</p>${r.reason?`<p>${esc(r.reason)}</p>`:''}<small>法规依据</small><p>${esc(typeof(r.law_article||r.legal_basis||r.article)==='object'?JSON.stringify(r.law_article||r.legal_basis||r.article):(r.law_article||r.legal_basis||r.article||r.law_basis||'见完整审核报告'))}</p><small>修改建议</small><p>${esc(r.fix||r.suggestion||r.recommendation||'请结合审核报告处理')}</p></div>`).join('')}`}
function detailPage(id){current=id;const t=tasks.find(x=>x.id===id);if(!t){$('#main').innerHTML=empty('正在读取任务','请稍候');api('/api/tasks/'+id).then(x=>{tasks.push(x);if(current===id)detailPage(id)}).catch(e=>{$('#main').innerHTML=empty('无法读取任务',esc(e.message))});return}const rounds=[...t.rounds].sort((a,b)=>a.index-b.index);const active=rounds.find(x=>x.index===selectedRound)||rounds.at(-1);const running=['queued','running'].includes(t.status);$('#main').innerHTML=`<a class="back" href="#history">← 返回任务记录</a><div class="topline"><div><div class="eyebrow">TASK ${(t.mode==='upload'?'上传审核':'生成审核')} · ${t.id.slice(0,8).toUpperCase()}</div><h1>${esc(t.inputs.product_name)}</h1><span class="quiet">提交于 ${date(t.created_at)} · ${rounds.length||0} 个海报版本</span></div>${pill(t.status)}</div><div class="progress-box ${t.status==='passed'?'done':running?'':'warn'}"><div class="${running?'spinner':'progress-icon'}">${running?'':t.status==='passed'?'✓':'!'}</div><div><div class="progress-title">${esc(t.stage)}</div><span class="quiet">${running?'任务在后台继续执行，可以离开页面后返回查看。':t.status==='passed'?'通过版图片与审核记录已保存到本地。':'未通过的海报不会提供通过版下载。'}</span></div></div><div class="preview-layout"><section class="card"><div class="section-head"><h2>海报版本</h2><span class="quiet">${active?esc(active.label):'等待生成'}</span></div><div class="tabs">${rounds.map(r=>`<button class="${active?.index===r.index?'selected':''}" data-round="${r.index}">${esc(r.label)}</button>`).join('')}</div><div class="poster-area">${active?.image?`<img src="${esc(active.image)}" alt="${esc(active.label)}海报">${active.report?.decision!=='PASS'?'<div class="preview-warning">审核预览 · 尚未通过，请勿对外使用</div>':''}`:empty(running?'海报正在准备中':'暂无可用图片',running?'生成后将在这里展示实际海报':'可以查看审核报告或补充需求后重试')}</div><div class="actions">${t.status==='passed'?`<a class="btn primary" href="/api/tasks/${t.id}/download">↓ 下载通过版</a>`:''}<a class="btn" href="/api/tasks/${t.id}/report">下载审核报告</a>${!running?'<button class="btn" id="reuse">补充需求重新提交</button>':''}</div><details><summary>查看提交的需求</summary>${Object.entries({产品名称:t.inputs.product_name,产品真实信息:t.inputs.product_facts,设计要求:t.inputs.design_request}).map(([k,v])=>`<div class="detail-row"><span>${k}</span><p>${esc(v)}</p></div>`).join('')}</details></section><div><section class="card"><div class="section-head"><h2>审核结论</h2><span class="quiet">${active?esc(active.label):'等待审核'}</span></div>${riskMarkup(active?.report)}</section><section class="card spaced"><h2>处理进度</h2><ol class="timeline">${t.events.slice(-12).map(e=>`<li>${esc(e.label)}<time>${date(e.time)}</time></li>`).join('')||'<li>等待工作流开始</li>'}</ol><details><summary>运行信息</summary><p class="quiet">执行引擎：Dify<br>运行编号：${esc(t.workflow_run_id||'尚未分配')}</p></details></section></div></div>`;document.querySelectorAll('[data-round]').forEach(b=>b.onclick=()=>{selectedRound=Number(b.dataset.round);detailPage(id)});if($('#reuse'))$('#reuse').onclick=()=>{if(t.mode==='upload'){window.pendingUploadInputs=t.inputs;uploadPending=null;sessionStorage.removeItem('uploadSubmission');location.hash='upload';return}window.pendingInputs=t.inputs;requestKey=null;pendingSubmission=null;sessionStorage.removeItem('pendingSubmission');location.hash='new'}}
function guidePage(){current=null;$('#main').innerHTML=`<div class="eyebrow">HOW IT WORKS</div><h1>网站与 Dify，怎样一起工作？</h1><p class="lead">支持从需求生成海报，也支持上传已有海报直接审核。两种入口均由 Dify 执行审核。</p><section class="card"><h2>一次提交的完整路径</h2><div class="architecture"><div class="node"><strong>用户网站</strong><small>填写需求 · 查看结果 · 下载</small></div><span class="arrow">→</span><div class="node"><strong>平台后台</strong><small>保存任务 · 安全调用 · 归档图片</small></div><span class="arrow">→</span><div class="node"><strong>Dify 工作流</strong><small>生成 · 审核 · 修改 · 复审</small></div></div><p class="guide-copy">Dify 将执行进度和结果返回后台，后台把它们保存为任务记录，再展示到网站。刷新或关闭网页，不会取消后台任务。</p></section><div class="guide-grid spaced"><section class="card guide-copy"><h2>为什么保留 Dify 工作流？</h2><p>在这个平台中，Dify 是审核执行引擎。海报生成、实际图片识别、法规判断、风险分支和自动修改都在同一个流程中执行。</p><p>它让审核规则集中维护：调整法规依据或修改策略时，可以修改并发布工作流，无需把整套审核逻辑重新写进网页。</p><p>同时保留节点运行记录，便于定位失败原因、复查审核依据。技术上也能用代码重写这些能力，但当前已验证的流程可以直接复用。</p></section><section class="card guide-copy"><h2>两种入口如何进入工作流？</h2><p>“上传海报审核”将原图送入独立视觉审核分支，跳过生图。返回风险及修改建议，保留原图；修改后可重新上传复审。</p><p>产品名称 → <code>product_name</code><br>产品真实信息 → <code>product_facts</code><br>设计与文案要求 → <code>design_request</code></p><p>点击“生成并审核”，网站先创建任务。后台调用 Dify 的 <code>POST /v1/workflows/run</code>，使用流式响应接收节点状态，再转换成“生成中”“审核中”“修改中”。</p><p>调用密钥只保存在后台。网页不会直接获得 Dify 或模型服务密钥。</p></section><section class="card guide-copy"><h2>通过条件在哪里判断？</h2><p>Dify 先完成严格校验与风险分支。后台还会检查最终结果：流程执行成功、结论为 PASS、风险列表为空、无需人工核实，且最终图片已经保存。</p><p>只有满足全部条件，网站才允许下载通过版。处理中、失败或需人工判断的任务，不能通过修改网页状态来绕过下载控制。</p></section><section class="card guide-copy"><h2>第一版的使用范围</h2><p>当前是运行在这台电脑上的内部版本，任务记录与海报保存在本地。需保持本地平台服务和 Dify 运行。</p><p>最多自动修改两次；无法可靠识别或仍有风险时停止导出。自动审核基于已提供的法规与产品事实，不等于法律保证。</p><p>对外提供服务前，再部署服务器并增加登录、权限与数据管理。</p></section></div>`}
async function refresh(){if(polling)return;polling=true;try{const [health,list]=await Promise.all([api('/api/health'),api('/api/tasks')]);configured=health.configured;$('#connection').textContent=configured?'Dify 接入已配置':'等待配置 Dify 接入';$('#connection').classList.toggle('ready',configured);const changed=JSON.stringify(list)!==JSON.stringify(tasks);tasks=list;if(uploadPending){const accepted=list.find(t=>t.request_key===uploadPending.request_key);if(accepted){uploadPending=null;sessionStorage.removeItem('uploadSubmission');location.hash='task/'+accepted.id}}if(pendingSubmission){const accepted=list.find(t=>t.request_key===pendingSubmission.request_key);if(accepted){pendingSubmission=null;requestKey=null;sessionStorage.removeItem('pendingSubmission');location.hash='task/'+accepted.id}}if(changed&&(route()==='history'||route().startsWith('task/')))render()}catch(err){$('#connection').textContent='本地服务连接中断';$('#connection').classList.remove('ready')}finally{polling=false}}
window.addEventListener('hashchange',navigate);render();refresh();setInterval(refresh,2500);

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_review_tasks',title:'查看海报审核任务',description:'读取本地平台海报任务的状态；不创建任务或触发模型调用。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(){return (await api('/api/tasks')).map(t=>({id:t.id,product:t.inputs.product_name,status:t.status,stage:t.stage}))}})).catch(()=>{})}catch{}}
